In part 1 we made every new Google Form lead ping your phone instantly. Instant alerts are great, but on a busy day some leads still slip. This part adds a safety net: one email every morning listing every lead that hasn't been handled yet.
What you'll build
A Status column in your responses sheet (new / called / closed)
A time-driven Apps Script trigger that runs at 08:00
One digest email: new leads from the last 24 h + anything still new after 24 h, each with a tel: link
Cost: $0. Time: ~10 minutes.
Open the form's response sheet. In the first empty column header type Status. Leave it empty; the script treats empty as new.
Extensions → Apps Script, paste:
const SHEET_NAME = 'Form Responses 1';
const PHONE_COL_NAME = 'Phone';
const NAME_COL_NAME = 'Name';
const TO = Session.getEffectiveUser().getEmail();

function dailyDigest() {
  const sh = SpreadsheetApp.getActive().getSheetByName(SHEET_NAME);
  const rows = sh.getDataRange().getValues();
  const head = rows.shift();
  const iTime = 0, iName = head.indexOf(NAME_COL_NAME),
        iPhone = head.indexOf(PHONE_COL_NAME), iStatus = head.indexOf('Status');
  const now = Date.now(), DAY = 864e5;
  const fresh = [], stale = [];
  rows.forEach(r => {
    const st = String(r[iStatus] || 'new').toLowerCase();
    if (st !== 'new') return;
    const age = now - new Date(r[iTime]).getTime();
    (age < DAY ? fresh : stale).push(r);
  });
  if (!fresh.length && !stale.length) return; // nothing to do, no email
  const line = r => `<li>${r[iName]} – <a href="tel:${r[iPhone]}">${r[iPhone]}</a> (${new Date(r[iTime]).toLocaleString()})</li>`;
  const html = `<h3>New in last 24h: ${fresh.length}</h3><ul>${fresh.map(line).join('')}</ul>` +
               `<h3>Still not called (24h+): ${stale.length}</h3><ul>${stale.map(line).join('')}</ul>`;
  MailApp.sendEmail({to: TO, subject: `Leads digest: ${fresh.length} new, ${stale.length} waiting`, htmlBody: html});
}

